/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { DeviceScreen } from "../../src/device/DeviceScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { RadioactivityAndStatisticsPreferencesModel } from "../../src/preferences/RadioactivityAndStatisticsPreferencesModel.js";
import RadioactivityAndStatisticsColors from "../../src/RadioactivityAndStatisticsColors.js";
import { SimulationScreen } from "../../src/simulation/SimulationScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from radioactivityAndStatisticsQueryParameters.
  const simPreferences = new RadioactivityAndStatisticsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new SimulationScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().simulationStringProperty,
      tandem: Tandem.ROOT.createTandem("simulationScreen"),
      backgroundColorProperty: RadioactivityAndStatisticsColors.backgroundColorProperty,
    }),
    new DeviceScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().deviceStringProperty,
      tandem: Tandem.ROOT.createTandem("deviceScreen"),
      backgroundColorProperty: RadioactivityAndStatisticsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { RadioactivityAndStatisticsColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
